const YEAR_COLORS=["#4e79a7","#f28e2b","#59a14f","#e15759","#b07aa1","#76b7b2","#243f33"];
const MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];
const requestedPage=new URLSearchParams(location.search).get("page");
const initialPage=["seasonality","overview","cumulative"].includes(requestedPage)?requestedPage:"overview";
const state={raw:null,daily:[],locations:[],locationById:new Map(),forecastData:null,forecastById:new Map(),allRegionsData:null,region:"ALL",company:"ALL",estate:"ALL",year:"ALL",startMonth:0,page:initialPage,years:[],forecastStartYear:null,forecastEndYear:null};
const $=id=>document.getElementById(id);
const parseDate=s=>new Date(`${s}T00:00:00`);
const iso=d=>d.toISOString().slice(0,10);
const fmt=n=>new Intl.NumberFormat("en-GB",{maximumFractionDigits:1}).format(n);
const svg=(name,attrs={})=>{const e=document.createElementNS("http://www.w3.org/2000/svg",name);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e};

function prepareDaily(records){
  const tools=new Map();
  records.forEach(r=>{const key=`${r[0]}|${r[1]}|${r[4]}|${r[3]}`;tools.set(key,Math.max(tools.get(key)??-Infinity,r[5]));});
  const days=new Map();
  tools.forEach((value,key)=>{const [company,estate,date]=key.split("|");const dayKey=`${company}|${estate}|${date}`;if(!days.has(dayKey))days.set(dayKey,[]);days.get(dayKey).push(value);});
  return [...days].map(([key,values])=>{const [company,estate,date]=key.split("|");return{company,estate,date,value:values.reduce((a,b)=>a+b,0)/values.length};}).sort((a,b)=>a.date.localeCompare(b.date));
}
function locationFor(company,estate){return state.locationById.get(`${company}${estate}`)}
function matchesLocation(location){return(state.region==="ALL"||location.region===state.region)&&(state.company==="ALL"||location.company===state.company)&&(state.estate==="ALL"||location.estate===state.estate)}
function visibleLocations(){return state.locations.filter(matchesLocation)}
function visibleDaily(){return state.daily.filter(r=>{const location=locationFor(r.company,r.estate);return(state.region==="ALL"||(location&&location.region===state.region))&&(state.company==="ALL"||r.company===state.company)&&(state.estate==="ALL"||r.estate===state.estate)});}
function visibleCompanies(){
  const grouped=new Map();visibleDaily().forEach(r=>{if(!grouped.has(r.company))grouped.set(r.company,new Map());const estates=grouped.get(r.company);if(!estates.has(r.estate))estates.set(r.estate,[]);estates.get(r.estate).push(r);});return grouped;
}
function averageByDate(rows){const m=new Map();rows.forEach(r=>{if(!m.has(r.date))m.set(r.date,[]);m.get(r.date).push(r.value)});return [...m].map(([date,v])=>({date,value:v.reduce((a,b)=>a+b,0)/v.length})).sort((a,b)=>a.date.localeCompare(b.date));}
function dayOfYear(date){const d=parseDate(date);return Math.floor((Date.UTC(2000,d.getMonth(),d.getDate())-Date.UTC(2000,0,1))/86400000);}
function seriesByYear(rows){
  const grouped=new Map();rows.forEach(r=>{const year=Number(r.date.slice(0,4));if(state.year!=="ALL"&&year!==Number(state.year))return;if(!grouped.has(year))grouped.set(year,[]);grouped.get(year).push([dayOfYear(r.date),r.value]);});
  return [...grouped].sort((a,b)=>a[0]-b[0]).map(([year,values])=>({year,values:values.sort((a,b)=>a[0]-b[0])}));
}
function lineColor(year,years){const index=years.indexOf(year);return YEAR_COLORS[Math.min(YEAR_COLORS.length-1,Math.round(index*Math.max(1,YEAR_COLORS.length-1)/Math.max(1,years.length-1)))];}
function showTooltip(event,html){const tip=$("chartTooltip");tip.innerHTML=html;tip.hidden=false;const x=Math.min(window.innerWidth-280,event.clientX+14),y=Math.max(8,event.clientY-20);tip.style.left=`${x}px`;tip.style.top=`${y}px`}
function hideTooltip(){$("chartTooltip").hidden=true}
function createSeasonChart(rows,large=false){
  const element=svg("svg",{class:"season-chart",role:"img","aria-label":"Daily rainfall seasonality chart"});const series=seriesByYear(averageByDate(rows)),years=series.map(s=>s.year),latest=Math.max(...years);if(!series.length)return element;
  requestAnimationFrame(()=>drawSeason(element,series,latest,large));return element;
}
