  chart.innerHTML="";const width=Math.max(chart.clientWidth,260),height=chart.clientHeight||180,m={top:8,right:8,bottom:25,left:large?42:33},iw=width-m.left-m.right,ih=height-m.top-m.bottom,maxY=Math.max(10,...series.flatMap(s=>s.values.map(v=>v[1]))),yMax=Math.ceil(maxY/25)*25,x=v=>m.left+v/365*iw,y=v=>m.top+ih-v/yMax*ih;
  [0,.5,1].forEach((f,i)=>{const yy=m.top+ih*f;chart.append(svg("line",{x1:m.left,x2:width-m.right,y1:yy,y2:yy,class:"grid-line"}));const t=svg("text",{x:m.left-6,y:yy+3,"text-anchor":"end",class:"axis-text"});t.textContent=fmt(yMax*(1-f));chart.append(t)});
  [[0,"Jan"],[91,"Apr"],[182,"Jul"],[274,"Oct"],[365,"Dec"]].forEach(([d,label],i)=>{const t=svg("text",{x:x(d),y:height-7,"text-anchor":i===0?"start":i===4?"end":"middle",class:"axis-text"});t.textContent=label;chart.append(t)});
  const years=series.map(s=>s.year);series.forEach(s=>{const d=s.values.map((v,i)=>`${i?"L":"M"}${x(v[0]).toFixed(1)},${y(v[1]).toFixed(1)}`).join(" ");chart.append(svg("path",{d,class:"series-line",stroke:lineColor(s.year,years),"stroke-width":s.year===latest?3.2:1.15,opacity:s.year===latest?1:.8}));});
  const hover=svg("line",{y1:m.top,y2:m.top+ih,class:"hover-line",visibility:"hidden"});chart.append(hover);const hit=svg("rect",{x:m.left,y:m.top,width:iw,height:ih,fill:"transparent"});chart.append(hit);hit.addEventListener("mousemove",event=>{const rect=chart.getBoundingClientRect(),localX=(event.clientX-rect.left)*width/rect.width,target=Math.max(0,Math.min(365,Math.round((localX-m.left)/iw*365)));hover.setAttribute("x1",x(target));hover.setAttribute("x2",x(target));hover.setAttribute("visibility","visible");const label=new Date(Date.UTC(2000,0,1+target)).toLocaleDateString("en-GB",{day:"numeric",month:"short"});const rows=series.map(s=>{const exact=s.values.find(v=>v[0]===target);return `<div class="tooltip-row"><span><i style="background:${lineColor(s.year,years)}"></i>${s.year}</span><b>${exact?`${fmt(exact[1])} mm`:"No reading"}</b></div>`}).join("");showTooltip(event,`<strong>${label}</strong>${rows}`)});hit.addEventListener("mouseleave",()=>{hover.setAttribute("visibility","hidden");hideTooltip()});
