  const years=series.map(s=>s.year),latest=Math.max(...years);series.forEach(s=>{const d=s.values.map((v,i)=>`${i?"L":"M"}${x(v[0]).toFixed(1)},${y(v[1]).toFixed(1)}`).join(" ");chart.append(svg("path",{d,class:"series-line",stroke:lineColor(s.year,years),"stroke-width":s.year===latest?3.8:1.5,opacity:s.year===latest?1:.85}));});
  const hover=svg("line",{y1:m.top,y2:m.top+ih,class:"hover-line",visibility:"hidden"});chart.append(hover);const hit=svg("rect",{x:m.left,y:m.top,width:iw,height:ih,fill:"transparent"});chart.append(hit);hit.addEventListener("mousemove",event=>{const rect=chart.getBoundingClientRect(),localX=(event.clientX-rect.left)*width/rect.width,target=Math.max(0,Math.min(365,Math.round((localX-m.left)/iw*365)));hover.setAttribute("x1",x(target));hover.setAttribute("x2",x(target));hover.setAttribute("visibility","visible");const start=new Date(2000,state.startMonth,1),date=new Date(start);date.setDate(date.getDate()+target);const label=date.toLocaleDateString("en-GB",{day:"numeric",month:"short"});const rows=series.map(s=>{const exact=s.values.find(v=>v[0]===target);return `<div class="tooltip-row"><span><i style="background:${lineColor(s.year,years)}"></i>${s.year}/${String(s.year+1).slice(-2)}</span><b>${exact?`${fmt(exact[1])} mm`:"No reading"}</b></div>`}).join("");showTooltip(event,`<strong>Day ${target+1} · ${label}</strong>${rows}`)});hit.addEventListener("mouseleave",()=>{hover.setAttribute("visibility","hidden");hideTooltip()});
