  const baseline=new Map();buckets.forEach(bucket=>{if(bucket.year>=state.forecastStartYear&&bucket.year<=state.forecastEndYear&&bucket.days.size===7){if(!baseline.has(bucket.week))baseline.set(bucket.week,[]);baseline.get(bucket.week).push(bucket.total)}});
  const historical=[...baseline].map(([week,values])=>({week,average:mean(values),min:Math.min(...values),max:Math.max(...values),years:values.length})).sort((a,b)=>a.week-b.week),source=state.forecastById.get(location.id),today=state.forecastData?.as_of_date||iso(new Date()),currentYear=Number(today.slice(0,4)),currentBuckets=new Map(),addCurrent=(date,value,kind)=>{const info=isoWeekInfo(date);if(info.year!==currentYear)return;if(!currentBuckets.has(info.week))currentBuckets.set(info.week,{week:info.week,sapValue:0,externalValue:0,sapDays:0,externalDays:0});const bucket=currentBuckets.get(info.week);if(kind==="sap"){bucket.sapValue+=Number(value||0);bucket.sapDays+=1}else{bucket.externalValue+=Number(value||0);bucket.externalDays+=1}};
  sapRows.filter(r=>r.date.slice(0,4)===String(currentYear)).forEach(r=>addCurrent(r.date,r.value,"sap"));
  const actualDates=source?.actual_dates||[],actualValues=source?.actual_rainfall_mm||[],externalDaily=[];actualDates.forEach((date,index)=>{if(date<today&&(!latestSapDate||date>latestSapDate)){const value=Number(actualValues[index]||0);externalDaily.push({date,value});addCurrent(date,value,"external")}});
  const current=[...currentBuckets.values()].sort((a,b)=>a.week-b.week),sapActual=current.filter(d=>d.sapDays).map(d=>({week:d.week,value:d.sapValue,days:d.sapDays})),externalActual=current.filter(d=>d.externalDays&&!d.sapDays).map(d=>({week:d.week,value:d.externalValue,sapDays:0,externalDays:d.externalDays}));if(externalActual.length&&sapActual.length){const lastSap=[...sapActual].reverse().find(row=>row.week<externalActual[0].week);if(lastSap)externalActual.unshift({...lastSap,bridge:true,externalDays:0,sapDays:lastSap.days})}
  const forecastBuckets=new Map(),forecastDates=source?.forecast_dates||source?.dates||[],forecastValues=source?.forecast_rainfall_mm||source?.rainfall_mm||[];forecastDates.forEach((date,index)=>{if(date<today)return;const info=isoWeekInfo(date);if(!forecastBuckets.has(info.week))forecastBuckets.set(info.week,{week:info.week,value:0,days:0,start:date,end:date});const bucket=forecastBuckets.get(info.week);bucket.value+=Number(forecastValues[index]||0);bucket.days+=1;bucket.end=date});
  const forecast=[...forecastBuckets.values()].sort((a,b)=>a.week-b.week),firstForecastWeek=forecast[0]?.week??Infinity,completedSap=sapActual.filter(row=>row.week<firstForecastWeek),completedExternal=externalActual.filter(row=>row.week<firstForecastWeek),lastObserved=[...completedSap,...completedExternal.filter(row=>!row.bridge)].sort((a,b)=>a.week-b.week).at(-1);if(forecast.length&&lastObserved)forecast.unshift({...lastObserved,bridge:true,days:0});
