  const forecast=combine("forecast",(week,rows)=>({week,value:mean(rows.map(row=>row.value)),days:Math.round(mean(rows.map(row=>row.days))||0),start:rows.map(row=>row.start).filter(Boolean).sort()[0],end:rows.map(row=>row.end).filter(Boolean).sort().at(-1)})),lastObserved=[...sapActual,...externalActual.filter(row=>!row.bridge)].sort((a,b)=>a.week-b.week).at(-1);if(forecast.length&&lastObserved)forecast.unshift({...lastObserved,bridge:true,days:0});
