function createAllRegionsChart(series){const chart=svg("svg",{class:"forecast-chart all-regions-weekly-chart",role:"img","aria-label":`All Regions weekly rainfall seasonality for ${series.label}`});requestAnimationFrame(()=>drawAllRegionsChart(chart,series));return chart}
