  chart.innerHTML="";const width=Math.max(chart.clientWidth,360),height=chart.clientHeight||185,m={top:10,right:10,bottom:28,left:44},iw=width-m.left-m.right,ih=height-m.top-m.bottom,values=series.rows.flatMap(row=>[row.current,row.min,row.max]).filter(Number.isFinite),maxY=Math.max(25,...values),yMax=Math.ceil(maxY/25)*25,x=week=>m.left+(week-1)/52*iw,y=value=>m.top+ih-value/yMax*ih;
