function selectedAreaName(locations){const regions=[...new Set(locations.map(x=>x.region))];if(state.region!=="ALL")return state.region;if(regions.length===1)return regions[0];if(state.company!=="ALL")return `Company ${state.company}`;if(state.estate!=="ALL")return `Estate ${state.estate}`;return "All Regions"}
function renderOverview(){
  const locations=visibleLocations(),rows=visibleDaily(),empty=$("historyEmpty");empty.hidden=locations.length>0;if(!locations.length)return;
  const latest=rows.reduce((m,r)=>r.date>m?r.date:m,""),end=parseDate(latest),dow=(end.getDay()+6)%7,currentStart=new Date(end);currentStart.setDate(end.getDate()-dow);const previousStart=new Date(currentStart);previousStart.setDate(currentStart.getDate()-7),previousEnd=new Date(previousStart);previousEnd.setDate(previousStart.getDate()+dow);
  const average=(items,start,finish)=>{const filtered=items.filter(r=>r.date>=iso(start)&&r.date<=iso(finish));return filtered.length?mean(filtered.map(r=>r.value)):null};
  const current=average(rows,currentStart,end),previous=average(rows,previousStart,previousEnd);$("overviewEstates").textContent=locations.length;$("overviewLatest").textContent=displayDate(latest);$("overviewCurrentWeek").textContent=current==null?"—":`${fmt(current)} mm/day`;$("overviewPreviousWeek").textContent=previous==null?"—":`${fmt(previous)} mm/day`;
  const body=$("overviewTableBody");body.innerHTML="";[...new Set(locations.map(x=>x.region))].sort().forEach(region=>{const regionLocations=locations.filter(x=>x.region===region),ids=new Set(regionLocations.map(x=>x.id)),regionRows=rows.filter(r=>ids.has(`${r.company}${r.estate}`)),regionLatest=regionRows.reduce((m,r)=>r.date>m?r.date:m,"");const tr=document.createElement("tr");tr.innerHTML=`<td>${region}</td><td>${regionLocations.length}</td><td>${displayDate(regionLatest)}</td><td>${average(regionRows,currentStart,end)==null?"—":`${fmt(average(regionRows,currentStart,end))} mm/day`}</td><td>${average(regionRows,previousStart,previousEnd)==null?"—":`${fmt(average(regionRows,previousStart,previousEnd))} mm/day`}</td>`;body.append(tr)});
}
