function renderAll(){const rows=visibleDaily(),locations=visibleLocations(),parts=[];if(state.region!=="ALL")parts.push(state.region);parts.push(state.company==="ALL"?"All companies":state.company);parts.push(state.estate==="ALL"?"All estates":`Estate ${state.estate}`);$("selectionLabel").textContent=parts.join(" · ");$("recordCount").textContent=`${locations.length} plantations · ${rows.length.toLocaleString()} daily records`;if(state.page==="seasonality")renderRainfallSeasonality();if(state.page==="overview")renderOverview();if(state.page==="cumulative")renderCumulative()}
