document.querySelectorAll(".tabs button").forEach(b=>b.addEventListener("click",()=>{state.page=b.dataset.page;document.querySelectorAll(".tabs button").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.id===`${state.page}Page`));requestAnimationFrame(renderAll)}));
document.querySelectorAll(".page").forEach(page=>page.classList.toggle("active",page.id===`${state.page}Page`));
