const allRegionsDataUrl=location.pathname.includes("/inhouse/")?"/api/data":"data/all_regions_dashboard.json";
Promise.all(["data/rainfall_daily.json","data/plantations.json","data/forecast_14day.json",allRegionsDataUrl].map(url=>fetch(url).then(r=>r.ok?r.json():Promise.reject(new Error(`${url} load failed: ${r.status}`))))).then(([rainfall,plantations,forecast,allRegions])=>{state.raw=rainfall;state.daily=prepareDaily(rainfall.records);state.locations=plantations.locations;state.locationById=new Map(state.locations.map(l=>[l.id,l]));state.forecastData=forecast;state.forecastById=new Map(forecast.forecasts.map(f=>[f.id,f]));state.allRegionsData=allRegions;state.years=[...new Set(state.daily.map(r=>Number(r.date.slice(0,4))))].sort();const latestDate=parseDate(state.daily.at(-1).date),baselineYears=state.years.filter(y=>y<Math.max(...state.years));state.forecastStartYear=baselineYears[0]??state.years[0];state.forecastEndYear=baselineYears.at(-1)??state.years.at(-1);$("dataThrough").textContent=latestDate.toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric"});const first=forecast.forecasts[0],actualEnd=first?.actual_dates?.at(-1),forecastStart=(first?.forecast_dates||first?.dates||[])[0],forecastEnd=(first?.forecast_dates||first?.dates||[]).at(-1);$("forecastCoverage").textContent=forecastStart&&forecastEnd?`External actual through ${displayDate(actualEnd)} · Forecast ${displayDate(forecastStart)}–${displayDate(forecastEnd)} · ${state.locations.length} plantations`:"Forecast unavailable";populateFilters()}).catch(err=>{document.querySelector("main").innerHTML=`<div class="empty"><strong>Dashboard data could not be loaded.</strong><br>${err.message}</div>`});
